<template><section class="admin-page"><AdminNav/><header><p class="eyebrow">Finance</p><h1>Payroll</h1><p>Record crew wage payments for each pay period.</p></header><p v-if="message" :class="['message',error?'error':'success']">{{message}}</p><div class="layout"><form class="card" @submit.prevent="save"><h2>Record payment</h2><label>Employee<select v-model="form.employee_id" required><option value="" disabled>Select employee</option><option v-for="e in employees" :key="e.id" :value="e.id">{{e.name}}</option></select></label><label>Amount (R)<input v-model.number="form.amount" required min="1" type="number" step=".01"/></label><label>Pay period<input v-model.trim="form.period" required placeholder="August 2026"/></label><label>Payment date<input v-model="form.payment_date" required type="date"/></label><label>Status<select v-model="form.status"><option value="paid">Paid</option><option value="pending">Pending</option></select></label><button>Record payment</button></form><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Period</th><th>Amount</th><th>Date</th><th>Status</th></tr></thead><tbody><tr v-for="item in records" :key="item.id"><td><strong>{{item.employee_name}}</strong><small>{{item.employee_role}}</small></td><td>{{item.period}}</td><td>R{{Number(item.amount).toFixed(2)}}</td><td>{{date(item.payment_date)}}</td><td><span :class="item.status">{{item.status}}</span></td></tr><tr v-if="!records.length"><td colspan="5" class="empty">No payroll records yet.</td></tr></tbody></table></div></div></section></template>
<script setup>import{onMounted,reactive,ref}from'vue';import api from'../../api.js';import AdminNav from'./AdminNav.vue';const records=ref([]),employees=ref([]),message=ref(''),error=ref(false);const form=reactive({employee_id:'',amount:null,period:'',payment_date:new Date().toISOString().slice(0,10),status:'paid'});const date=v=>new Date(v).toLocaleDateString('en-ZA',{day:'numeric',month:'short',year:'numeric'});async function load(){try{const[p,e]=await Promise.all([api.get('/payroll'),api.get('/employees')]);records.value=p.data;employees.value=e.data.filter(x=>x.status==='active')}catch{error.value=true;message.value='Unable to load payroll.'}}async function save(){try{const {data}=await api.post('/payroll',{...form,employee_id:Number(form.employee_id)});message.value=data.message;error.value=false;Object.assign(form,{employee_id:'',amount:null,period:'',payment_date:new Date().toISOString().slice(0,10),status:'paid'});load()}catch(e){error.value=true;message.value=e.response?.data?.message||'Unable to record payment.'}}onMounted(load)</script>
<style scoped>.admin-page{width:min(1120px,100%);margin:auto;padding:2rem 1.5rem 4rem}header{margin:2rem 0 1rem}.eyebrow{color:var(--green);font-size:.75rem;font-weight:800;text-transform:uppercase;letter-spacing:.1em;margin:0}h1{color:var(--green-dark);margin:.2rem 0}header p:not(.eyebrow){color:var(--text-muted);margin:0}.layout{display:grid;grid-template-columns:320px 1fr;gap:1.25rem}.card,.table-wrap{background:#fff;border:1px solid var(--border);border-radius:12px;padding:1.2rem}.card h2{margin:0;color:var(--green-dark)}label{display:grid;gap:.3rem;margin:.75rem 0;font-weight:700;font-size:.85rem;color:var(--green-dark)}input,select{padding:.65rem;border:1px solid var(--border);border-radius:7px}button{cursor:pointer;border:0;padding:.65rem .8rem;border-radius:7px;background:var(--green);color:var(--green-deeper);font-weight:800}.table-wrap{overflow:auto;padding:0}table{border-collapse:collapse;width:100%;min-width:570px}th,td{padding:1rem;text-align:left;border-bottom:1px solid var(--border)}th{font-size:.75rem;text-transform:uppercase;color:var(--text-muted)}td small{display:block;color:var(--text-muted)}td span{padding:.2rem .5rem;border-radius:99px;font-size:.75rem;font-weight:800;text-transform:capitalize}.paid{color:#286033;background:#e6f5e8}.pending{color:#7a5300;background:#fff1cb}.message{padding:.7rem;border-radius:7px}.success{background:#e7f5e8;color:#286033}.error{background:#fff0f0;color:#9b2525}.empty{text-align:center;color:var(--text-muted)}@media(max-width:760px){.layout{grid-template-columns:1fr}}</style>
